"""DS4_FAST_TRITON: per-callsite cached fast path for Triton kernel launches.

Stock ``triton.runtime.jit.JITFunction.run`` re-runs argument binding,
per-argument specialization (dtype string, pointer alignment, 2 GB buffer-ops
window, int divisibility/equal-to-1) and cache-key construction on EVERY
launch.  That cost is pure Python and grows linearly with argument count, so
the many-argument triton_kernels/aiter kernels in the decode step pay it
hundreds of times per step.

This module wraps ``JITFunction.run`` with a per-JITFunction dict keyed by a
cheap tuple that is *sufficient* to pin down the compiled-kernel choice and
the launch configuration:

  - constexpr params: exact value
  - tensor args: (dtype, shape, data_ptr()%16==0, untyped_storage<=2GiB)
  - int/bool args: exact value  (covers equal-to-1 and %16 specialization)
  - float args: type only        (floats are never runtime-specialized)
  - None: None

On a hit it launches the cached CompiledKernel directly via ``kernel.run``
with the cached grid, skipping the binder/specialization/cache-key machinery.
On a miss (or any situation the fast path cannot prove equivalent: warmup,
pre-run hooks, launch hooks, instrumentation, unhashable args, *args/kw-only
signatures) it defers to the stock ``run``.

Exactly-launch-equivalent by construction:
  - the key strictly refines triton's own specialization inputs, so a hit can
    never map to a kernel the stock path would not have chosen;
  - grid callables are evaluated once per key on the bound-arg dict (shapes
    and all non-tensor values are part of the key, so the result is constant
    per key);
  - the current stream is still queried per launch (side-stream safe).

Not preserved on the hit path (both are debug guards, never load-bearing in
production): the used-global-vals mutation check and pre/post launch hooks
(when hooks are installed the fast path disables itself).

Enable with DS4_FAST_TRITON=1 (importing the module installs the patch only
when the env var is set, mirroring ds4_tiny_routing).
"""

import inspect
import os

_INSTALLED = False


def _build_state(jit_fn):
    """Precompute per-JITFunction binding metadata. Returns None if the
    signature cannot be handled by the fast path."""
    import triton  # noqa: F401

    sig = jit_fn.signature
    params = jit_fn.params
    names = []
    for p in sig.parameters.values():
        if p.kind not in (
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
            inspect.Parameter.POSITIONAL_ONLY,
        ):
            return None
        names.append(p.name)
    if len(names) != len(params):
        return None

    is_constexpr = tuple(p.is_constexpr for p in params)

    # Generated fast binder: positional/keyword -> tuple in signature order,
    # plus leftover kwargs (num_warps & co -> compile options).
    ns = {}
    arglist = []
    for p in sig.parameters.values():
        if p.default is inspect.Parameter.empty:
            arglist.append(p.name)
        else:
            ns[f"_ds4_default_{p.name}"] = p.default
            arglist.append(f"{p.name}=_ds4_default_{p.name}")
    body = (
        f"def _ds4_bind({', '.join(arglist + ['**_ds4_opts'])}):\n"
        f"    return ({', '.join(names) + (',' if names else '')}), _ds4_opts\n"
    )
    try:
        exec(body, ns)
    except SyntaxError:
        return None
    return {
        "bind": ns["_ds4_bind"],
        "names": tuple(names),
        "is_constexpr": is_constexpr,
        "cache": {},
    }


def install():
    global _INSTALLED
    if _INSTALLED:
        return
    import torch
    from triton import knobs
    from triton.runtime import driver
    from triton.runtime.jit import JITFunction

    Tensor = torch.Tensor
    _MAX32 = 2**31 - 1
    _orig_run = JITFunction.run

    def run(self, *args, grid, warmup, **kwargs):
        # Situations the fast path does not model -> stock run.
        # launch hooks may be plain callables (active) or HookChain objects
        # (active only when their .calls list is non-empty, e.g. proton).
        rt = knobs.runtime
        eh = rt.launch_enter_hook
        xh = rt.launch_exit_hook
        if (
            warmup
            or self.pre_run_hooks
            or (eh is not None and getattr(eh, "calls", True))
            or (xh is not None and getattr(xh, "calls", True))
            or rt.add_stages_inspection_hook is not None
            or rt.debug
            or kwargs.get("debug", self.debug)
        ):
            return _orig_run(self, *args, grid=grid, warmup=warmup, **kwargs)

        state = getattr(self, "_ds4ft", False)
        if state is False:
            state = _build_state(self)
            self._ds4ft = state
        if state is None:
            return _orig_run(self, *args, grid=grid, warmup=warmup, **kwargs)

        try:
            vals, opts = state["bind"](*args, **kwargs)
        except TypeError:
            return _orig_run(self, *args, grid=grid, warmup=warmup, **kwargs)

        # Build the key. Strictly refines triton's specialization inputs.
        key = [None] * len(vals)
        i = 0
        try:
            for v, is_ce in zip(vals, state["is_constexpr"]):
                if is_ce:
                    # constexpr: exact value (tl.dtype/str/int/tuple/...).
                    key[i] = v
                elif isinstance(v, Tensor):
                    key[i] = (
                        v.dtype,
                        v.shape,
                        v.data_ptr() & 15 == 0,
                        v.untyped_storage().nbytes() <= _MAX32,
                    )
                elif v is None or type(v) in (int, bool, str):
                    key[i] = v
                elif type(v) is float:
                    key[i] = float
                else:
                    # Unknown arg object (custom pointer wrappers, ...):
                    # cannot cheaply prove launch equivalence.
                    return _orig_run(
                        self, *args, grid=grid, warmup=warmup, **kwargs
                    )
                i += 1
            # A non-callable grid is an independent launch input: it must be
            # part of the key (callable grids are pure functions of the
            # bound args, which the key already covers).
            if not callable(grid):
                key.append(tuple(grid))
            if opts:
                k = (tuple(key), tuple(sorted(opts.items())))
            else:
                k = tuple(key)
            entry = state["cache"].get(k)
        except TypeError:
            return _orig_run(self, *args, grid=grid, warmup=warmup, **kwargs)

        device = driver.active.get_current_device()
        stream = driver.active.get_current_stream(device)

        if entry is None or entry[3] != device:
            kernel = _orig_run(self, *args, grid=grid, warmup=warmup, **kwargs)
            if kernel is None:
                return None
            if callable(grid):
                g = grid(dict(zip(state["names"], vals)))
            else:
                g = grid
            gs = len(g)
            grid_tup = (g[0], g[1] if gs > 1 else 1, g[2] if gs > 2 else 1)
            try:
                # Resolve .run once (it lazily _init_handles on first access).
                state["cache"][k] = (kernel, kernel.run, grid_tup, device)
            except TypeError:
                pass
            return kernel

        kernel, krun, (g0, g1, g2), _dev = entry
        krun(
            g0,
            g1,
            g2,
            stream,
            kernel.function,
            kernel.packed_metadata,
            None,  # launch_metadata (hooks are None on this path)
            None,
            None,
            *vals,
        )
        return kernel

    JITFunction.run = run
    _INSTALLED = True


if os.environ.get("DS4_FAST_TRITON", "0") == "1":
    install()
